.tl-switcher-container {
  position: relative !important;
  z-index: 10 !important;
}

.tl-switcher-container .tl-dropdown,
.tl-switcher-container .tl-options {
  z-index: 999999 !important;
}

.tl-switcher-container.desktop .tl-dropdown,
.tl-switcher-container.desktop .tl-options {
  left: auto !important;
  right: 0 !important;
}
