/* Language dropdown options: native name → English name */
.tl-switcher.tl-language .tl-option[data-value="en"] .tl-label,
.tl-switcher.tl-language .tl-option[data-value="da"] .tl-label,
.tl-switcher.tl-language .tl-option[data-value="fr"] .tl-label,
.tl-switcher.tl-language .tl-option[data-value="de"] .tl-label,
.tl-switcher.tl-language .tl-option[data-value="it"] .tl-label,
.tl-switcher.tl-language .tl-option[data-value="es"] .tl-label {
  font-size: 0 !important;
}

.tl-switcher.tl-language .tl-option[data-value="en"] .tl-label::before { content: "English"; font-size: 14px; }
.tl-switcher.tl-language .tl-option[data-value="da"] .tl-label::before { content: "Danish"; font-size: 14px; }
